import sys

def main():
    input = sys.stdin.read().split()
    ptr = 0
    T = int(input[ptr])
    ptr += 1
    for _ in range(T):
        N = int(input[ptr])
        ptr += 1
        goals = list(map(int, input[ptr:ptr+N]))
        ptr += N
        max_diff = -1
        found = False
        for i in range(N):
            for j in range(i+1, N):
                if goals[j] > goals[i]:
                    diff = goals[j] - goals[i]
                    if diff > max_diff:
                        max_diff = diff
                        found = True
        if found:
            print(max_diff)
        else:
            print("UNFIT")

main()
